local function shouldUseAirPlatform()
	if not isAnyCombatActive() then return false end
	if State.MoveMode == "Walk" then
		return (State.AttackPosition == "above" or State.AttackPosition == "below")
	end
	return State.FreezeAnimOnActive
end

local function setCharacterFreezeAnim(shouldFreeze)
	local char,_,hum=getCharacterParts()
	if not char or not hum then return end
	local animateScript=char:FindFirstChild("Animate")
	if animateScript and animateScript:IsA("LocalScript") then
		animateScript.Disabled = shouldFreeze
	end
	hum.AutoRotate = not shouldFreeze
	hum.PlatformStand = shouldFreeze
	if not shouldFreeze then
		hum:ChangeState(Enum.HumanoidStateType.GettingUp)
	else
		local animator=hum:FindFirstChildOfClass("Animator")
		if animator then
			for _,track in ipairs(animator:GetPlayingAnimationTracks()) do track:Stop(0) end
		end
		for _,joint in ipairs(char:GetDescendants()) do
			if joint:IsA("Motor6D") then joint.Transform=CFrame.new() end
		end
	end
end

local function refreshFreezeState()
	setCharacterFreezeAnim(shouldUseAirPlatform())
end

local function bindCharacterEvents(char)local hum=char:WaitForChild("Humanoid",5)if not hum then return end local animator=hum:WaitForChild("Animator",5)if not animator then return end animator.AnimationPlayed:Connect(function(track)if shouldUseAirPlatform() then track:Stop(0)end end)task.defer(refreshFreezeState)end if player.Character then task.spawn(bindCharacterEvents,player.Character)end player.CharacterAdded:Connect(bindCharacterEvents)

RunService.Stepped:Connect(function()
	if shouldUseAirPlatform() then
		local char,_,hum=getCharacterParts()
		if char and hum then
			hum.PlatformStand=true
			for _,joint in ipairs(char:GetDescendants()) do
				if joint:IsA("Motor6D") then joint.Transform=CFrame.new() end
			end
		end
	end
end)

UserInputService.JumpRequest:Connect(function()if State.InfJump then local _,_,hum=getCharacterParts()if hum then hum:ChangeState(Enum.HumanoidStateType.Jumping)end end end)local function performDash()if not State.InfDash then return end local _,hrp,hum=getCharacterParts()if not hrp or not hum then return end local moveDir=hum.MoveDirection if moveDir.Magnitude<0.05 then local look=hrp.CFrame.LookVector local flat=Vector3.new(look.X,0,look.Z)moveDir=(flat.Magnitude>0.001)and flat.Unit or Vector3.new(0,0,-1)end hrp.AssemblyLinearVelocity=Vector3.new(moveDir.X*State.DashPower,math.max(hrp.AssemblyLinearVelocity.Y,12),moveDir.Z*State.DashPower)end UserInputService.InputBegan:Connect(function(input,gameProcessed)if gameProcessed then return end if input.KeyCode==Enum.KeyCode.Q then performDash()end end)local function findClosestAnyMob(maxRange)local _,playerHRP=getCharacterParts()if not playerHRP then return nil,math.huge end local closestMob,closestDist=nil,maxRange for obj in pairs(mobCache)do local valid,_,mobHRP=isValidMob(obj)if valid then local dist=(mobHRP.Position-playerHRP.Position).Magnitude if dist<=closestDist then closestDist=dist closestMob=obj end elseif not obj or not obj.Parent then mobCache[obj]=nil end end return closestMob,closestDist end local function scanGroupedMobs(radius)local _,playerHRP=getCharacterParts()if not playerHRP then return{}end local groups={}for obj in pairs(mobCache)do local valid,_,mobHRP=isValidMob(obj)if valid then local dist=(mobHRP.Position-playerHRP.Position).Magnitude if dist<=radius then local name=obj.Name if not groups[name]then groups[name]={Name=name,Count=0,NearestDist=math.floor(dist)}end groups[name].Count+=1 if dist<groups[name].NearestDist then groups[name].NearestDist=math.floor(dist)end end elseif not obj or not obj.Parent then mobCache[obj]=nil end end local result={}for _,info in pairs(groups)do table.insert(result,info)end table.sort(result,function(a,b)return a.NearestDist<b.NearestDist end)return result end local function pickNearbyMobByName(mobName,maxRange)local _,playerHRP=getCharacterParts()if not playerHRP or not mobName then return nil end local candidates={}for obj in pairs(mobCache)do if obj and obj.Name==mobName then local valid,_,mobHRP=isValidMob(obj)if valid then local dist=(mobHRP.Position-playerHRP.Position).Magnitude if dist<=maxRange then table.insert(candidates,{Model=obj,Distance=dist})end end end end if#candidates==0 then return nil end table.sort(candidates,function(a,b)return a.Distance<b.Distance end)local poolSize=math.min(#candidates,3)local weights={60,28,12}local totalWeight=0 for i=1,poolSize do totalWeight+=weights[i]end local roll=math.random(1,totalWeight)local acc=0 for i=1,poolSize do acc+=weights[i]if roll<=acc then return candidates[i].Model end end return candidates[1].Model end local function stopTween()if activeTween then activeTween:Cancel()activeTween=nil end end

local function getAttackPositionCFrame(targetHRP)
	local targetPos=targetHRP.Position
	local lookDir=targetHRP.CFrame.LookVector
	local flatDir=Vector3.new(lookDir.X,0,lookDir.Z)
	flatDir=(flatDir.Magnitude<0.001)and Vector3.new(0,0,-1)or flatDir.Unit
	if State.AttackPosition=="above" then
		local pos=targetPos+Vector3.new(0,State.VerticalOffset,0)
		return CFrame.lookAt(pos,pos+flatDir)*CFrame.Angles(math.rad(-State.AboveTiltAngle),0,0)
	elseif State.AttackPosition=="below" then
		local pos=targetPos-Vector3.new(0,State.VerticalOffset,0)
		return CFrame.lookAt(pos,pos+flatDir)*CFrame.Angles(math.rad(State.AboveTiltAngle),0,0)
	elseif State.AttackPosition=="behind" then
		return CFrame.lookAt(targetPos-(flatDir*State.HorizontalDist),targetPos)
	elseif State.AttackPosition=="front" then
		return CFrame.lookAt(targetPos+(flatDir*State.HorizontalDist),targetPos)
	end
	return targetHRP.CFrame*CFrame.new(0,0,State.HorizontalDist)
end

local function moveToTarget(targetModel)
	local valid,_,targetHRP=isValidMob(targetModel)
	if not valid then return end
	local _,playerHRP,playerHum=getCharacterParts()
	if not playerHRP or not playerHum then return end
	if State.MoveMode=="Walk" then
		local goal=getAttackPositionCFrame(targetHRP)
		playerHum:MoveTo(goal.Position)
	end
	lastCombatPosition=playerHRP.Position
end

RunService.Heartbeat:Connect(function(dt)
	local char,hrp,hum=getCharacterParts()
	if not char or not hrp or not hum then return end
	if not isAnyCombatActive() then return end
	local valid,_,targetHRP=isValidMob(State.CurrentTarget)
	if not valid then return end

	local goal=getAttackPositionCFrame(targetHRP)
	local mode=State.MoveMode
	local offset=goal.Position-hrp.Position
	local dist=offset.Magnitude

	if mode=="Teleport" then
		hrp.AssemblyLinearVelocity=Vector3.zero
		hrp.AssemblyAngularVelocity=Vector3.zero
		local safeTpMax=22
		if dist<=safeTpMax then
			hrp.CFrame=goal
		else
			local safeStep=185*dt
			hrp.CFrame=CFrame.new(hrp.Position+offset.Unit*math.min(safeStep,dist))*goal.Rotation
		end
	elseif mode=="Tween" then
		hrp.AssemblyLinearVelocity=Vector3.zero
		hrp.AssemblyAngularVelocity=Vector3.zero
		local step=State.TweenSpeed*dt
		if dist<=step then
			hrp.CFrame=goal
		else
			hrp.CFrame=CFrame.new(hrp.Position+offset.Unit*step)*goal.Rotation
		end
	elseif mode=="Walk" then
		local isAirPos=(State.AttackPosition=="above" or State.AttackPosition=="below")
		local flatGoal=Vector3.new(goal.Position.X,hrp.Position.Y,goal.Position.Z)
		local flatDist=(flatGoal-hrp.Position).Magnitude

		if isAirPos then
			if flatDist>3.5 then
				hum.PlatformStand=false
				hum:MoveTo(flatGoal)
			else
				hum.PlatformStand=true
				hrp.AssemblyLinearVelocity=Vector3.zero
				hrp.AssemblyAngularVelocity=Vector3.zero
				hrp.CFrame=goal
			end
		else
			hum.PlatformStand=false
			if dist>2.5 then
				hum:MoveTo(goal.Position)
			else
				hrp.CFrame=CFrame.new(hrp.Position,Vector3.new(targetHRP.Position.X,hrp.Position.Y,targetHRP.Position.Z))
			end
		end
	end

	if State.AttackPosition=="below" and State.BelowNoclip then
		for _,part in ipairs(char:GetDescendants()) do
			if part:IsA("BasePart") then part.CanCollide=false end
		end
	end
end)

